declare(strict_types=1);session_start();require_once __DIR__.'/config/sales_step15.php';if(empty($_SESSION['invoice15_csrf']))$_SESSION['invoice15_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['invoice15_csrf'];$error=null;$success=null;$invoices=[];$invoice=null;$items=[];$orderId=(int)($_GET['order']??$_POST['order_id']??0);
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$id=sales_step15_generate_invoice($pdo,$orderId,(string)($_POST['invoice_date']??date('Y-m-d')));$success='Invoice #'.$id.' generated.';}$stmt=$pdo->prepare("SELECT i.*,o.order_date,sl.sale_status FROM sales_invoices i JOIN orders o ON o.id=i.order_id AND o.organization_id=i.organization_id JOIN product_sale_ledger sl ON sl.order_id=i.order_id AND sl.organization_id=i.organization_id WHERE i.organization_id=? ORDER BY i.invoice_date DESC,i.id DESC");$stmt->execute([$orgId]);$invoices=$stmt->fetchAll();if($orderId>0){$stmt=$pdo->prepare("SELECT i.*,o.order_date,q.quote_code FROM sales_invoices i JOIN orders o ON o.id=i.order_id AND o.organization_id=i.organization_id LEFT JOIN product_quote_order_links ql ON ql.order_id=o.id AND ql.organization_id=o.organization_id LEFT JOIN product_quotes q ON q.id=ql.quote_id AND q.organization_id=o.organization_id WHERE i.organization_id=? AND i.order_id=? LIMIT 1");$stmt->execute([$orgId,$orderId]);$invoice=$stmt->fetch()?:null;if($invoice){$stmt=$pdo->prepare("SELECT stock_no,product_name_snapshot,quantity,unit_mrp,unit_price,unit_vp,line_mrp,line_price,line_vp FROM product_order_items WHERE organization_id=? AND order_id=? ORDER BY id");$stmt->execute([$orgId,$orderId]);$items=$stmt->fetchAll();}}}catch(Throwable $e){$error=$e->getMessage();}
function si_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function si_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}function si_n(mixed $v):string{$x=number_format((float)$v,3,'.','');return rtrim(rtrim($x,'0'),'.');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Sales Invoice - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><style>@media print{.os-topbar,.os-sidebar,.no-print{display:none!important}.os-layout,.os-main{display:block!important;width:100%!important;margin:0!important}.os-card{box-shadow:none!important;border:0!important}}</style></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="sales_fulfillment.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 15 • Sales Invoice</small></span></a><div class="os-top-actions"><a class="os-btn" href="sales_fulfillment.php">Fulfillment</a><button class="os-btn primary" onclick="window.print()">Print / Save PDF</button></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">After-Sales</div><nav class="os-nav"><a href="customer_center.php"><i class="dot"></i>Customers</a><a href="sales_fulfillment.php"><i class="dot"></i>Fulfillment</a><a class="active" href="sales_invoice.php"><i class="dot"></i>Invoices</a><a href="sales_delivery.php"><i class="dot"></i>Delivery</a><a href="sales_returns.php"><i class="dot"></i>Returns</a><a href="sales_refunds.php"><i class="dot"></i>Refunds</a></nav></aside><main class="os-main"><section class="os-hero pp-hero no-print"><div class="os-kicker">STEP 15C • SALES INVOICE</div><h1>Freeze the original Product Sale into a print-ready customer invoice.</h1><p>Tax is not inferred. Returns and refunds remain separate credit/refund records so the original invoice stays historically correct.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'INVOICE CENTER LIVE':'Review required' ?></span><span class="os-chip"><?= count($invoices) ?> invoices</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Invoice diagnostic:</strong> <?= si_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Done:</strong> <?= si_h($success) ?></div><?php endif;?><?php if(!$error&&$orderId>0&&!$invoice):?><section class="os-card no-print" style="margin-top:14px"><h2>Generate Invoice for Order #<?= $orderId ?></h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= si_h($csrf) ?>"><input type="hidden" name="order_id" value="<?= $orderId ?>"><label>Invoice Date<input type="date" name="invoice_date" value="<?= si_h(date('Y-m-d')) ?>" required></label><button>Generate Immutable Invoice →</button></form></section><?php endif;?><?php if($invoice):?><section class="os-card" style="margin-top:14px"><div class="os-title-row"><div><h2>Healthcare Wellness Club</h2><p>Sales Invoice • <?= si_h($invoice['invoice_number']) ?></p></div><div><b>Date:</b> <?= si_h($invoice['invoice_date']) ?><br><b>Order:</b> #<?= (int)$invoice['order_id'] ?></div></div><div class="pp-grid" style="margin-top:14px"><div class="pp-span-6"><div class="pp-source"><b>Customer</b><span><?= si_h($invoice['customer_name_snapshot']?:'Customer snapshot unavailable') ?></span></div><div class="pp-source"><b>Mobile</b><span><?= si_h($invoice['mobile_snapshot']?:'—') ?></span></div><div class="pp-source"><b>Delivery / Billing Address</b><span><?= nl2br(si_h($invoice['address_snapshot']?:'—')) ?></span></div></div><div class="pp-span-6"><div class="pp-source"><b>Quote</b><span><?= si_h($invoice['quote_code']?:'—') ?></span></div><div class="pp-source"><b>Total VP</b><span><?= si_h(si_n($invoice['volume_points'])) ?></span></div><div class="pp-source"><b>Tax</b><span><?= si_m($invoice['tax_amount']) ?> • not inferred</span></div></div></div><div class="pp-table-wrap" style="margin-top:14px"><table class="pp-table"><thead><tr><th>Stock No.</th><th>Product</th><th>Qty</th><th>MRP</th><th>Sale Price</th><th>VP</th><th>Line Total</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?= si_h($i['stock_no']) ?></td><td><b><?= si_h($i['product_name_snapshot']) ?></b></td><td><?= si_h(si_n($i['quantity'])) ?></td><td><?= si_m($i['unit_mrp']) ?></td><td><?= si_m($i['unit_price']) ?></td><td><?= si_h(si_n($i['line_vp'])) ?></td><td><b><?= si_m($i['line_price']) ?></b></td></tr><?php endforeach;?></tbody></table></div><div class="pp-grid" style="margin-top:14px"><div class="pp-span-7"></div><div class="pp-span-5"><div class="pp-source"><b>Gross</b><span><?= si_m($invoice['gross_amount']) ?></span></div><div class="pp-source"><b>Discount / Saving</b><span><?= si_m($invoice['discount_amount']) ?></span></div><div class="pp-source"><b>Tax</b><span><?= si_m($invoice['tax_amount']) ?></span></div><div class="pp-source"><b>Invoice Total</b><span><strong><?= si_m($invoice['net_amount']) ?></strong></span></div></div></div><div class="os-footer-note"><strong>Invoice rule:</strong> this is the original sale snapshot. Customer returns create separate Credit/Return Notes and do not overwrite this invoice.</div></section><?php endif;?><?php if(!$invoice):?><section class="os-card no-print" style="margin-top:14px"><h2>Invoice Register</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Invoice</th><th>Date</th><th>Order</th><th>Customer</th><th>Net</th><th>VP</th><th>Status</th></tr></thead><tbody><?php foreach($invoices as $i):?><tr><td><a href="?order=<?= (int)$i['order_id'] ?>"><b><?= si_h($i['invoice_number']) ?></b></a></td><td><?= si_h($i['invoice_date']) ?></td><td>#<?= (int)$i['order_id'] ?></td><td><?= si_h($i['customer_name_snapshot']?:'—') ?></td><td><?= si_m($i['net_amount']) ?></td><td><?= si_h(si_n($i['volume_points'])) ?></td><td><?= si_h(strtoupper($i['status'])) ?></td></tr><?php endforeach;?><?php if(!$invoices):?><tr><td colspan="7">No sales invoices yet.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
